using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
    private readonly TicketModelTrainer _trainer;
    private readonly ILogger<TicketController> _logger;

    public TicketController(
        PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
        TicketModelTrainer trainer,
        ILogger<TicketController> logger)
    {
        _predictionPool = predictionPool;
        _trainer = trainer;
        _logger = logger;
    }

    [HttpPost("predict")]
    public ActionResult<PredictionResponse> Predict([FromBody] TicketRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        // Get label names from the model's output schema
        var labels = GetSlotNames();
        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < labels.Length && i < prediction.Score.Length; i++)
        {
            confidence[labels[i]] = prediction.Score[i];
        }

        _logger.LogInformation("Predicted {Category} for ticket: {Subject}",
            prediction.Category, request.Subject);

        return Ok(new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        });
    }

    [HttpGet("metrics")]
    public ActionResult<ModelMetrics> GetMetrics()
    {
        var metrics = _trainer.Metrics;
        if (metrics is null)
            return NotFound("Model has not been trained yet.");

        return Ok(metrics);
    }

    [HttpPost("train")]
    public ActionResult<ModelMetrics> Train()
    {
        _trainer.TrainAndEvaluate();
        return Ok(_trainer.Metrics);
    }

    private string[] GetSlotNames()
    {
        var mlContext = new MLContext();
        using var stream = System.IO.File.OpenRead(_trainer.GetModelPath());
        var model = mlContext.Model.Load(stream, out var schema);
        var scoreColumn = schema["Score"];
        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        scoreColumn.GetSlotNames(ref slotNames);
        return slotNames.DenseValues().Select(v => v.ToString()).ToArray();
    }
}

